def feature(s):
    sites = s.get('sites', ())
    n = len(sites)
    if n == 0:
        return 0.0
    occ = [max(0.0, float(t.get('occupancy', 1.0) or 0.0)) for t in sites]
    weight = sum(occ)
    if weight <= 0.0:
        return 0.0
    props = s.get('element_properties', {})
    chi = [props.get(t.get('element', ''), {}).get('eneg') for t in sites]
    neighbors = s.get('neighbors', ())
    near = [6.0] * n
    for b in neighbors:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A')
        if 0 <= i < n and 0 <= j < n and occ[j] > 0.0 and d is not None and 1e-8 < d < near[i]:
            near[i] = d
    total = 0.0
    for b in neighbors:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and 1e-8 < d <= 1.25 * near[i]:
            a = chi[i]
            c = chi[j]
            if a is not None and c is not None and math.isfinite(a) and math.isfinite(c):
                total += occ[i] * occ[j] * (a - c) ** 2 / d
    return float(0.5 * total / weight)

def feature(s):
    sites = s.get('sites', ())
    n = len(sites)
    if n == 0:
        return 0.0
    occ = [max(0.0, float(t.get('occupancy', 1.0) or 0.0)) for t in sites]
    props = s.get('element_properties', {})
    elements = [t.get('element', '') for t in sites]
    chi = [props.get(e, {}).get('eneg') for e in elements]
    neighbors = s.get('neighbors', ())
    near = [6.0] * n
    for b in neighbors:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A')
        if 0 <= i < n and 0 <= j < n and occ[j] > 0.0 and d is not None and 1e-8 < d < near[i]:
            near[i] = d
    counts = [0.0] * n
    sums = [0.0] * n
    for b in neighbors:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and 1e-8 < d <= 1.25 * near[i]:
            value = chi[j]
            if value is not None and math.isfinite(value):
                counts[i] += occ[j]
                sums[i] += occ[j] * value
    weights = {}
    first = {}
    second = {}
    for i in range(n):
        if counts[i] > 0.0 and occ[i] > 0.0:
            e = elements[i]
            value = sums[i] / counts[i]
            weights[e] = weights.get(e, 0.0) + occ[i]
            first[e] = first.get(e, 0.0) + occ[i] * value
            second[e] = second.get(e, 0.0) + occ[i] * value * value
    weight = sum(weights.values())
    if weight <= 0.0:
        return 0.0
    variance = sum(max(0.0, second[e] - first[e] * first[e] / weights[e]) for e in weights)
    return float(variance / weight)
